"""Build script — produces standalone binaries for the toolkit.

Three binaries:
  - mxwp-validator : the original .docx → DocumentJSON validator
  - mxwp-rules     : the RAG CLI (query / index / check)
  - mxwp-mcp       : the MCP stdio server

DESIGN: zero source duplication.

`validate.py` + `_settings_stub.py` are the only Python files *owned* by
this folder for the validator path. `docx_import` / `widget_markers` are
imported live from `apps/api/app/services/` at build time; PyInstaller's
dependency analyser follows the graph and snapshots them — so every push
that touches a widget rule produces a fresh validator binary.

For the RAG binaries (rules + mcp), the source is the toolkit's own
`rag/` folder plus `mcp/`, so no staging is required for them.

Usage:
    python build.py                   # build all three (current platform)
    python build.py --target validator
    python build.py --target rules
    python build.py --target mcp
    python build.py --onedir          # produce unpacked folders (debugging)

CI cross-platform builds run on `ubuntu-latest` and `windows-latest`.
"""
from __future__ import annotations

import argparse
import io
import os
import shutil
import subprocess
import sys
from pathlib import Path


if sys.platform == "win32":
    sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
    sys.stderr = io.TextIOWrapper(sys.stderr.buffer, encoding="utf-8", errors="replace")
os.environ.setdefault("PYTHONIOENCODING", "utf-8")


HERE = Path(__file__).resolve().parent
REPO = HERE.parent.parent
API_SRC = REPO / "apps" / "api" / "app" / "services"
SCHEMA = REPO / "packages" / "shared" / "schemas" / "document.json"


# ── spec templates ─────────────────────────────────────────────────


# Spec is fed Python Path objects so cross-platform path handling stays
# the OS's responsibility, not PyInstaller's `--add-data` mini-DSL (which
# uses `:` on POSIX and `;` on Windows and is fragile under shell escape).
_VALIDATOR_SPEC = """# Auto-generated by build.py — do not edit.
# -*- mode: python ; coding: utf-8 -*-

block_cipher = None

a = Analysis(
    [{entry}],
    pathex=[{stage}],
    binaries=[],
    datas=[({schema}, '.')],
    hiddenimports=[
        'docx_import',
        'widget_markers',
        'toc_extract',
        '_settings_stub',
        'jsonschema',
        'ulid',
    ],
    hookspath=[],
    hooksconfig={{}},
    runtime_hooks=[],
    excludes=[],
    win_no_prefer_redirects=False,
    win_private_assemblies=False,
    cipher=block_cipher,
    noarchive=False,
)
pyz = PYZ(a.pure, a.zipped_data, cipher=block_cipher)

if {onefile}:
    exe = EXE(
        pyz, a.scripts, a.binaries, a.zipfiles, a.datas, [],
        name='mxwp-validator',
        debug=False, bootloader_ignore_signals=False, strip=False, upx=False,
        console=True, disable_windowed_traceback=False,
        target_arch=None, codesign_identity=None, entitlements_file=None,
    )
else:
    exe = EXE(pyz, a.scripts, [], exclude_binaries=True,
              name='mxwp-validator', debug=False, strip=False, upx=False, console=True)
    coll = COLLECT(exe, a.binaries, a.zipfiles, a.datas,
                   strip=False, upx=False, name='mxwp-validator')
"""


# `mxwp-rules` ships the `rag/` package as-is. We also embed chunks.jsonl,
# index.lock, llm-system-prompt.md, llm-input-rules.md, and the schema so
# `mxwp-rules check` can run offline.
_RULES_SPEC = """# Auto-generated by build.py — do not edit.
# -*- mode: python ; coding: utf-8 -*-

block_cipher = None

a = Analysis(
    [{entry}],
    pathex=[{toolkit}],
    binaries=[],
    datas=[
        ({chunks}, 'rag'),
        ({lock}, 'rag'),
        ({system_prompt}, '.'),
        ({input_rules}, '.'),
        ({schema}, '.'),
    ],
    hiddenimports=[
        'rag.cli',
        'rag.chunker',
        'rag._bm25',
        'rag._lock',
        'rag.retriever',
        # st + openai are heavy and lazy-loaded; we still declare them
        # so the binary can find them when the user picks those backends.
        'rag._st',
        'rag._openai',
        'numpy',
        'sentence_transformers',
        'openai',
    ],
    hookspath=[],
    hooksconfig={{}},
    runtime_hooks=[],
    excludes=[],
    cipher=block_cipher,
    noarchive=False,
)
pyz = PYZ(a.pure, a.zipped_data, cipher=block_cipher)

if {onefile}:
    exe = EXE(
        pyz, a.scripts, a.binaries, a.zipfiles, a.datas, [],
        name='mxwp-rules',
        debug=False, bootloader_ignore_signals=False, strip=False, upx=False,
        console=True, disable_windowed_traceback=False,
    )
else:
    exe = EXE(pyz, a.scripts, [], exclude_binaries=True,
              name='mxwp-rules', debug=False, strip=False, upx=False, console=True)
    coll = COLLECT(exe, a.binaries, a.zipfiles, a.datas,
                   strip=False, upx=False, name='mxwp-rules')
"""


# `mxwp-mcp` is the awkward one: the toolkit has a local `mcp/` folder
# that name-collides with the installed `mcp` SDK. PyInstaller analyses
# imports statically — if the toolkit dir is on pathex, the local `mcp`
# (containing only an empty `__init__.py`) wins and bundles instead of
# the SDK. So we stage a flat folder containing a launcher + a `rag/`
# symlink and put ONLY that stage on pathex. The SDK comes from
# site-packages because nothing local shadows it.
_MCP_SPEC = """# Auto-generated by build.py — do not edit.
# -*- mode: python ; coding: utf-8 -*-

import sys
# Drop the toolkit dir from sys.path before resolving `mcp` so the local
# toolkit `mcp/` package (only a thin wrapper) doesn't shadow the SDK
# during collect_submodules.
sys.path = [p for p in sys.path if p not in ({toolkit_dir}, '', '.')]

from PyInstaller.utils.hooks import collect_submodules, collect_data_files

block_cipher = None

# Pull in every mcp.* + pydantic.* submodule. The SDK uses dynamic dispatch
# (anyio, fastmcp's tool registry) that PyInstaller can't trace statically,
# so a shotgun collect is safer than declaring each submodule by hand.
_mcp_hidden = collect_submodules('mcp')
_pyd_hidden = collect_submodules('pydantic') + collect_submodules('pydantic_core')

a = Analysis(
    [{entry}],
    pathex=[{stage}],
    binaries=[],
    datas=[
        ({chunks}, 'rag'),
        ({lock}, 'rag'),
        ({system_prompt}, '.'),
    ] + collect_data_files('mcp'),
    hiddenimports=[
        'mcp.server.fastmcp',
        'rag._bm25',
        'rag._st',
        'rag._openai',
        'rag.retriever',
        'numpy',
        'sentence_transformers',
        'openai',
    ] + _mcp_hidden + _pyd_hidden,
    hookspath=[],
    hooksconfig={{}},
    runtime_hooks=[],
    excludes=[],
    cipher=block_cipher,
    noarchive=False,
)
pyz = PYZ(a.pure, a.zipped_data, cipher=block_cipher)

if {onefile}:
    exe = EXE(
        pyz, a.scripts, a.binaries, a.zipfiles, a.datas, [],
        name='mxwp-mcp',
        debug=False, bootloader_ignore_signals=False, strip=False, upx=False,
        console=True,
    )
else:
    exe = EXE(pyz, a.scripts, [], exclude_binaries=True,
              name='mxwp-mcp', debug=False, strip=False, upx=False, console=True)
    coll = COLLECT(exe, a.binaries, a.zipfiles, a.datas,
                   strip=False, upx=False, name='mxwp-mcp')
"""


def run(cmd: list[str], **kw: object) -> None:
    print(f"\n$ {' '.join(cmd)}", flush=True)
    try:
        subprocess.check_call(cmd, **kw)
    except subprocess.CalledProcessError as e:
        print(f"\n[build] command failed with exit code {e.returncode}", flush=True)
        raise


def _preflight() -> None:
    print(f"[build] python      : {sys.version.splitlines()[0]}")
    print(f"[build] platform    : {sys.platform}")
    print(f"[build] HERE        : {HERE}")
    print(f"[build] REPO        : {REPO}")
    print(f"[build] API_SRC     : {API_SRC}  exists={API_SRC.exists()}")
    print(f"[build] SCHEMA      : {SCHEMA}  exists={SCHEMA.exists()}")
    import PyInstaller  # type: ignore[import-not-found]
    print(f"[build] PyInstaller : {PyInstaller.__version__}")


def _stage_validator(work_dir: Path) -> Path:
    """Stage validator source (with import patches) into a flat folder."""
    stage = work_dir / "stage-validator"
    if stage.exists():
        shutil.rmtree(stage)
    stage.mkdir(parents=True, exist_ok=True)
    shutil.copy(HERE / "src" / "validate.py", stage / "mxwp_validator.py")
    shutil.copy(HERE / "src" / "_settings_stub.py", stage / "_settings_stub.py")
    # Snapshot production imports. Two patches:
    #   1. `app.core.config` → toolkit stub.
    #   2. `from . import widget_markers as _wm` → flat import (stage is a
    #      flat folder, not a package).
    for fname in ("docx_import.py", "widget_markers.py", "toc_extract.py"):
        src_path = API_SRC / fname
        if not src_path.exists():
            print(f"  skipping {fname} (not present)")
            continue
        src_text = src_path.read_text(encoding="utf-8")
        patched = (
            src_text
            .replace(
                "from app.core.config import get_settings",
                "from _settings_stub import get_settings",
            )
            .replace(
                "from . import widget_markers as _wm",
                "import widget_markers as _wm",
            )
            .replace(
                "from . import toc_extract as _toc",
                "import toc_extract as _toc",
            )
        )
        (stage / fname).write_text(patched, encoding="utf-8")
        print(f"  staged {fname} ({len(patched)} bytes)")
    return stage


def _stage_mcp_entry(work_dir: Path) -> Path:
    """Stage a flat folder with launcher + a `rag` package copy.

    The stage folder is the *only* pathex entry for the MCP build, so the
    site-packages `mcp` SDK resolves cleanly (no local mcp/ shadowing).
    Returns the launcher path.
    """
    stage = work_dir / "stage-mcp"
    if stage.exists():
        shutil.rmtree(stage)
    stage.mkdir(parents=True, exist_ok=True)
    # Copy rag/ as a real package so `from rag._bm25 import …` resolves.
    shutil.copytree(
        HERE / "rag",
        stage / "rag",
        ignore=shutil.ignore_patterns(
            "__pycache__", "tests", "chunks.jsonl", "index.lock",
            "bm25.json", "embeddings.npz", "embeddings.jsonl",
            "openai_embeddings.npz", "openai_embeddings.jsonl",
        ),
    )
    launcher = stage / "_mxwp_mcp_launcher.py"
    server_src = (HERE / "mcp" / "server.py").read_text(encoding="utf-8")
    launcher.write_text(server_src, encoding="utf-8")
    return launcher


def _build_validator(work_dir: Path, bin_dir: Path, onefile: bool) -> Path:
    stage = _stage_validator(work_dir)
    spec_path = work_dir / "mxwp-validator.spec"
    spec_path.write_text(
        _VALIDATOR_SPEC.format(
            entry=repr(str(stage / "mxwp_validator.py")),
            stage=repr(str(stage)),
            schema=repr(str(SCHEMA)),
            onefile="True" if onefile else "False",
        ),
        encoding="utf-8",
    )
    print(f"[build] validator spec : {spec_path}")
    run([
        sys.executable, "-m", "PyInstaller", "--clean", "--noconfirm",
        "--distpath", str(work_dir / "dist-validator"),
        "--workpath", str(work_dir / "work-validator"),
        str(spec_path),
    ])
    return _collect(work_dir / "dist-validator", bin_dir, "mxwp-validator", onefile)


def _stage_rules_entry(work_dir: Path) -> Path:
    """Flat launcher that imports `rag.cli` as a top-level package.

    PyInstaller treats the entry script as `__main__` without a parent
    package, so `rag/__main__.py`'s relative `from .cli import main` would
    fail. The flat launcher just calls into the package.
    """
    stage = work_dir / "stage-rules"
    if stage.exists():
        shutil.rmtree(stage)
    stage.mkdir(parents=True, exist_ok=True)
    launcher = stage / "_mxwp_rules_launcher.py"
    launcher.write_text(
        "from __future__ import annotations\n"
        "import sys\n"
        "from rag.cli import main\n"
        "sys.exit(main())\n",
        encoding="utf-8",
    )
    return launcher


def _build_rules(work_dir: Path, bin_dir: Path, onefile: bool) -> Path:
    chunks = HERE / "rag" / "chunks.jsonl"
    lock = HERE / "rag" / "index.lock"
    if not chunks.exists() or not lock.exists():
        raise RuntimeError(
            f"rag/chunks.jsonl or rag/index.lock missing. "
            f"Run: python {HERE / 'rag' / 'chunker.py'}"
        )
    launcher = _stage_rules_entry(work_dir)
    spec_path = work_dir / "mxwp-rules.spec"
    spec_path.write_text(
        _RULES_SPEC.format(
            entry=repr(str(launcher)),
            toolkit=repr(str(HERE)),
            chunks=repr(str(chunks)),
            lock=repr(str(lock)),
            system_prompt=repr(str(HERE / "llm-system-prompt.md")),
            input_rules=repr(str(HERE / "llm-input-rules.md")),
            schema=repr(str(SCHEMA)),
            onefile="True" if onefile else "False",
        ),
        encoding="utf-8",
    )
    print(f"[build] rules spec     : {spec_path}")
    run([
        sys.executable, "-m", "PyInstaller", "--clean", "--noconfirm",
        "--distpath", str(work_dir / "dist-rules"),
        "--workpath", str(work_dir / "work-rules"),
        str(spec_path),
    ])
    return _collect(work_dir / "dist-rules", bin_dir, "mxwp-rules", onefile)


def _build_mcp(work_dir: Path, bin_dir: Path, onefile: bool) -> Path:
    launcher = _stage_mcp_entry(work_dir)
    chunks = HERE / "rag" / "chunks.jsonl"
    lock = HERE / "rag" / "index.lock"
    spec_path = work_dir / "mxwp-mcp.spec"
    spec_path.write_text(
        _MCP_SPEC.format(
            entry=repr(str(launcher)),
            stage=repr(str(launcher.parent)),
            chunks=repr(str(chunks)),
            lock=repr(str(lock)),
            system_prompt=repr(str(HERE / "llm-system-prompt.md")),
            onefile="True" if onefile else "False",
            toolkit_dir=repr(str(HERE)),
        ),
        encoding="utf-8",
    )
    print(f"[build] mcp spec       : {spec_path}")
    run([
        sys.executable, "-m", "PyInstaller", "--clean", "--noconfirm",
        "--distpath", str(work_dir / "dist-mcp"),
        "--workpath", str(work_dir / "work-mcp"),
        str(spec_path),
    ])
    return _collect(work_dir / "dist-mcp", bin_dir, "mxwp-mcp", onefile)


def _collect(dist_dir: Path, bin_dir: Path, name: str, onefile: bool) -> Path:
    exe_suffix = ".exe" if sys.platform == "win32" else ""
    if onefile:
        src = dist_dir / f"{name}{exe_suffix}"
        dst = bin_dir / f"{name}-{sys.platform}{exe_suffix}"
        if dst.exists():
            dst.unlink()
        shutil.move(str(src), str(dst))
        print(f"[OK] produced binary: {dst}")
    else:
        src = dist_dir / name
        dst = bin_dir / f"{name}-{sys.platform}"
        if dst.exists():
            shutil.rmtree(dst)
        shutil.move(str(src), str(dst))
        print(f"[OK] produced folder: {dst}")
    return dst


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--onedir", action="store_true", help="Produce unpacked folders instead of single files.")
    parser.add_argument("--clean", action="store_true", help="Wipe bin/_build before building.")
    parser.add_argument(
        "--target",
        choices=["all", "validator", "rules", "mcp"],
        default="all",
        help="Which binary to build (default: all three).",
    )
    args = parser.parse_args()

    try:
        _preflight()
    except Exception as e:
        print(f"[build] preflight failed: {e!r}")
        return 2

    if not (API_SRC / "docx_import.py").exists() and args.target in ("all", "validator"):
        print(f"ERROR: cannot find {API_SRC / 'docx_import.py'}", file=sys.stderr)
        return 2
    if not SCHEMA.exists():
        print(f"ERROR: cannot find {SCHEMA}", file=sys.stderr)
        return 2

    bin_dir = HERE / "bin"
    work_dir = HERE / "_build"
    if args.clean and bin_dir.exists():
        shutil.rmtree(bin_dir)
    if args.clean and work_dir.exists():
        shutil.rmtree(work_dir)
    bin_dir.mkdir(parents=True, exist_ok=True)
    work_dir.mkdir(parents=True, exist_ok=True)

    onefile = not args.onedir
    artifacts: list[Path] = []
    if args.target in ("all", "validator"):
        artifacts.append(_build_validator(work_dir, bin_dir, onefile))
    if args.target in ("all", "rules"):
        artifacts.append(_build_rules(work_dir, bin_dir, onefile))
    if args.target in ("all", "mcp"):
        artifacts.append(_build_mcp(work_dir, bin_dir, onefile))

    print("\nQuick sanity:", flush=True)
    for art in artifacts:
        try:
            subprocess.check_call([str(art), "--version"], timeout=15)
        except Exception as e:
            print(f"  ({art.name} sanity skipped — {e})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
